definition.script:
pipeline {
    agent any

    tools {
        maven 'maven3.9'
        jdk 'jdk17'
    }

    stages {
        stage('Git Checkout') {
            steps {
                git branch: 'main', url: 'https://github.com/sandhya-en/Boardgame.git'
            }
        }
         stage('test') {
             when {
                 changeset "test.txt"
             }
            steps {
                echo 'mvn test'
            }
        }
         stage('Build') {
            steps {
                echo 'mvn package'
            }
        }
    }

    post {
        always{
            echo "Cleaning up Workspace"
            cleanWs()
        }
    }
}
